INSERT INTO cms_pages (slug, title, content, active) VALUES
  ('about', 'About HomeHaat', '<p>HomeHaat (a placeholder demo brand) brings together everyday household essentials inspired by the Indian <em>haat</em> — the neighbourhood market where quality and value meet.</p><h2>What we believe</h2><ul><li>Durable products that suit Indian kitchens and homes</li><li>Honest, GST-inclusive pricing</li><li>Delivery across India with Cash on Delivery</li></ul><p>This website is a demo built for review purposes. Brands and products are fictional.</p>', 1),
  ('shipping-returns', 'Shipping & Returns', '<h2>Shipping</h2><ul><li><strong>Standard delivery</strong>: ₹79, free on orders of ₹999 and above. 4–6 working days.</li><li><strong>Express delivery</strong>: ₹149. 1–2 working days in metro cities.</li><li>We ship to all serviceable PIN codes across India.</li></ul><h2>Cash on Delivery</h2><p>COD is available on orders up to ₹10,000.</p><h2>Returns & refunds</h2><ul><li>Return any unused product within <strong>7 days</strong> of delivery.</li><li>Refunds to the original payment method in 5–7 working days. COD refunds go to your bank account/UPI.</li><li>Electrical appliances are covered by the brand warranty after the return window.</li></ul>', 1),
  ('privacy', 'Privacy Policy', '<p>This is a placeholder privacy policy for the demo store. We collect only the information needed to process your orders — name, contact details, delivery address and order history — and never sell it to third parties.</p><p>Payments are processed by our payment partner; we do not store card numbers.</p><p>Replace this text with your legal team''s policy, compliant with the Digital Personal Data Protection Act, 2023.</p>', 1),
  ('terms', 'Terms of Use', '<p>These are placeholder terms for the demo store. By using this website you agree to our policies on orders, pricing, delivery and returns.</p><p>All prices are in Indian Rupees (₹) and inclusive of GST. Product images are illustrative.</p><p>Disputes are subject to the jurisdiction of courts in Chennai, Tamil Nadu.</p>', 1);
INSERT INTO site_config (config_key, value) VALUES
