  ('announcement', '{"text":"🪔 Festive offer: use FESTIVE250 for flat ₹250 off on orders above ₹1,999 · Free standard delivery above ₹999","link":"/products.html?offers=1","active":true}'),
  ('footer', '{"about":"HomeHaat is a demo online store for thoughtfully designed household essentials — from kitchen to bedroom — delivered across India.","columns":[{"title":"Shop","links":[{"label":"Kitchen & Dining","href":"/products.html?category=kitchen-dining"},{"label":"Home Décor","href":"/products.html?category=home-decor"},{"label":"Bedroom","href":"/products.html?category=bedroom"},{"label":"Offers","href":"/products.html?offers=1"}]},{"title":"Help","links":[{"label":"Shipping & Returns","href":"/page.html?slug=shipping-returns"},{"label":"Track Order","href":"/account.html#orders"},{"label":"Contact Us","href":"/contact.html"}]},{"title":"Company","links":[{"label":"About Us","href":"/page.html?slug=about"},{"label":"Privacy Policy","href":"/page.html?slug=privacy"},{"label":"Terms of Use","href":"/page.html?slug=terms"}]}],"social":{"instagram":"#","facebook":"#","youtube":"#"},"copyright":"© {year} HomeHaat (demo). All prices in ₹ and inclusive of GST."}'),
  ('contact', '{"address":"HomeHaat Retail Pvt. Ltd. (demo), 2nd Floor, 45 Cathedral Road, Gopalapuram, Chennai, Tamil Nadu 600086","phone":"+91 44 4000 1234","email":"support@homehaat.example","whatsapp":"919876500000","hours":[{"days":"Monday – Saturday","time":"9:30 AM – 7:30 PM"},{"days":"Sunday","time":"10:00 AM – 4:00 PM"}],"lat":13.0475,"lng":80.257,"faqs":[{"q":"How long does delivery take?","a":"Standard delivery takes 4–6 working days; Express delivery takes 1–2 working days in metro cities."},{"q":"Is Cash on Delivery available?","a":"Yes, COD is available on orders up to ₹10,000 across most PIN codes."},{"q":"How do I return a product?","a":"Raise a return within 7 days of delivery from My Account → Orders, or contact us. Refunds are processed within 5–7 working days."},{"q":"Are prices inclusive of GST?","a":"Yes. All prices shown are inclusive of GST and a GST invoice is provided with every order."}]}'),
  ('settings', '{"delivery":{"standard":{"label":"Standard","charge":79,"freeAbove":999,"eta":"4–6 working days"},"express":{"label":"Express","charge":149,"freeAbove":null,"eta":"1–2 working days"}},"cod":{"enabled":true,"maxOrderValue":10000,"minOrderValue":0},"tax":{"pricesIncludeGst":true,"gstin":"33AABCH1234Z1Z5","legalName":"HomeHaat Retail Pvt. Ltd. (demo)","state":"Tamil Nadu","invoicePrefix":"HH/INV/"},"lowStockThreshold":5,"email":{"smtp":{"host":"","port":587,"secure":false,"user":"","pass":"","from":"HomeHaat <no-reply@homehaat.example>"},"demoMode":true,"adminEmail":"admin@demo.com","enabled":{"welcome":true,"password_reset":true,"order_placed":true,"payment_success":true,"payment_failed":true,"order_shipped":true,"out_for_delivery":true,"delivered":true,"cancelled":true,"refund":true,"contact_admin":true,"test":true}}}');
